from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 6 and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 6 and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 6 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and (r,c) not in seen:
                out[r][c] = 4
    return out

if __name__ == '__main__':
    demo=[[6,6,8,6,6,6,6,6,6,6,6,6,6],[6,8,8,8,6,6,6,6,6,6,6,6,6],[8,8,6,8,8,8,8,8,8,8,8,8,8],[6,8,6,8,6,6,6,6,6,6,6,6,6],[6,8,8,8,6,6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6,6,6,6,6,6],[6,6,6,6,6,6,6,6,6,6,6,6,6]]
    got=transform(demo)
    assert got[2][2] == 4 and got[3][2] == 4
    test=[[6]*14 for _ in range(14)]
    ones={ (r,8) for r in range(0,6)} | {(3,c) for c in range(8,14)} | {(5,c) for c in range(5,12)} | {(r,5) for r in range(5,11)} | {(r,11) for r in range(5,11)} | {(10,c) for c in range(5,12)} | {(r,8) for r in range(10,14)} | {(7,c) for c in range(11,14)}
    for r,c in ones: test[r][c]=5
    ans=transform(test)
    assert all(ans[r][c] == 4 for r in range(6,10) for c in range(6,11))
    print('\n'.join(' '.join(map(str,row)) for row in ans))
